<script lang="ts">
import type{HudProfile}from './launcher_plugins';
import{CROSSHAIR_SHAPES}from './crosshair';
import CrosshairRender from './CrosshairRender.svelte';
let{profile=$bindable(),onchange=()=>{}}:{profile:HudProfile;onchange?:()=>void}=$props();
let c=$derived(profile.crosshair),painting=false,ink=true;
function paint(event:PointerEvent){const node=document.elementFromPoint(event.clientX,event.clientY)?.closest('[data-pixel]') as HTMLElement|null;if(!node)return;const i=Number(node.dataset.pixel);if(i>=0&&i<c.pixels.length)c.pixels[i]=ink;}
function begin(event:PointerEvent){if(event.button!==0&&event.button!==2)return;event.preventDefault();painting=true;ink=event.button!==2;const target=event.currentTarget as HTMLElement;target.setPointerCapture(event.pointerId);paint(event);}
function finish(){if(painting){painting=false;onchange();}}
function grid(size:15|17){c.grid=size;c.pixels=Array(size*size).fill(false);onchange();}
</script>
<section class="studio"><header><h3>Estudio de mira e impactos</h3><label class="check"><input type="checkbox" bind:checked={c.enabled} onchange={onchange}/>Mira personalizada</label></header><p>El diseño funciona en el overlay. Ocultar la mira original y recibir impactos confirmados requiere un adaptador del motor compatible.</p>
<div class="preview"><CrosshairRender settings={c} cooldown={.72}/><small>Vista previa · enfriamiento de ejemplo</small></div>
<div class="presets">{#each CROSSHAIR_SHAPES as shape}<button class:active={c.shape===shape.id} onclick={()=>{c.shape=shape.id;onchange();}}>{shape.name}</button>{/each}</div>
{#if c.shape==='pixels'}<div class="pixel-tools"><button onclick={()=>grid(15)}>15 × 15</button><button onclick={()=>grid(17)}>17 × 17</button><button onclick={()=>{c.pixels.fill(false);onchange();}}>Limpiar lienzo</button><small>Clic: pintar · clic derecho: borrar</small></div><div class="pixels" role="group" aria-label="Lienzo pixel-art de la mira" style:--cells={c.grid} onpointerdown={begin} onpointermove={(e)=>{if(painting)paint(e);}} onpointerup={finish} onpointercancel={finish} oncontextmenu={(e)=>e.preventDefault()}>{#each c.pixels as value,i}<button data-pixel={i} class:painted={value} aria-label={`Píxel ${i%c.grid+1}, ${Math.floor(i/c.grid)+1}`} aria-pressed={value} onkeydown={(e)=>{if(e.key===' '||e.key==='Enter'){e.preventDefault();c.pixels[i]=!value;onchange();}}}></button>{/each}</div>{/if}
<div class="controls">{#each [['size','Longitud',1,18,.5],['thickness','Grosor',.5,6,.5],['gap','Separación central',0,12,.5],['dot','Punto central',.5,6,.5],['outline','Borde oscuro',0,3,.5],['opacity','Opacidad',.1,1,.05]] as [key,label,min,max,step]}<label>{label}<output>{c[key as 'size'|'thickness'|'gap'|'dot'|'outline'|'opacity']}</output><input type="range" {min} {max} {step} bind:value={c[key as 'size'|'thickness'|'gap'|'dot'|'outline'|'opacity']} oninput={onchange}/></label>{/each}</div>
<div class="colors">{#each [['color','Mira'],['hit_color','Impacto'],['hostile_color','Enemigo'],['passive_color','Pasivo'],['range_color','Dentro de alcance']] as [key,label]}<label>{label}<input type="color" bind:value={c[key as 'color'|'hit_color'|'hostile_color'|'passive_color'|'range_color']} oninput={onchange}/></label>{/each}</div>
<label class="check"><input type="checkbox" bind:checked={c.chroma} onchange={onchange}/>Chroma RGB</label><label class="check"><input type="checkbox" bind:checked={c.dynamic} onchange={onchange}/>Expandir al moverse o atacar</label><label class="check"><input type="checkbox" bind:checked={c.target_color} onchange={onchange}/>Color según objetivo y distancia</label><label class="check"><input type="checkbox" bind:checked={c.hitmarker} onchange={onchange}/>Indicador de impacto confirmado</label>
<label>Duración del impacto <output>{c.hit_duration} ms</output><input type="range" min="60" max="1000" step="20" bind:value={c.hit_duration} oninput={onchange}/></label><label>Enfriamiento de ataque<select bind:value={c.cooldown} onchange={onchange}><option value="off">Oculto</option><option value="ring">Anillo</option><option value="bar">Barra</option></select></label><small>La recarga completa no garantiza un golpe crítico: también depende del movimiento y las reglas del juego.</small></section>
<style>.studio{display:grid;gap:16px}.studio h3{margin:0}.studio p,.studio small{font-size:11px;color:#b9adc5;line-height:1.6}.preview{height:150px;background:radial-gradient(ellipse,#353542,#121218);display:grid;place-items:center;position:relative;border:1px solid #ffffff18}.preview small{position:absolute;bottom:8px}.presets,.colors,.pixel-tools{display:flex;gap:7px;flex-wrap:wrap}.studio button,.studio select{background:#ffffff08;color:inherit;border:1px solid #ffffff25;padding:8px;cursor:pointer;font:inherit;font-size:11px}.presets .active{border-color:var(--hud-accent,#a855f7);background:#a855f722}.controls{display:grid;grid-template-columns:1fr 1fr;gap:14px}.studio label{display:grid;gap:6px;font-size:11px}.studio output{color:#bba3ce}.studio .check{display:flex;align-items:center;gap:8px}input[type=range]{width:100%;accent-color:var(--hud-accent,#a855f7)}input[type=color]{width:66px;height:30px;padding:0;border:0;background:none}.pixels{display:grid;grid-template-columns:repeat(var(--cells),1fr);width:min(100%,306px);aspect-ratio:1;touch-action:none;border:1px solid #a855f777;gap:1px;background:#ffffff22}.pixels button{background:#0b0b0f;min-width:0;min-height:0;padding:0;border:0}.pixels button.painted{background:#f1e4ff}.pixels button:focus-visible{outline:2px solid #06b6d4;z-index:1}</style>
